<template>
 <section class="container py-4 management-page">
  <header class="management-heading"><div><p class="management-eyebrow">WhatsApp</p><h1>{{ tr('¿Qué puedo hacer por WhatsApp?','What can I do through WhatsApp?') }}</h1><p>{{ tr('Ejemplos prácticos para secretaría, pastores y departamentos. Cada persona solo puede usar las funciones permitidas en su cuenta.','Practical examples for clerks, pastors and departments. Each person can only use features allowed for their account.') }}</p></div></header>
  <section class="management-surface wa-start"><h2>{{ tr('Empieza aquí','Start here') }}</h2><ol><li>{{ tr('Activa el asistente en tu cuenta. Si el encargado ya registró tu número, envía Hola al WhatsApp de la iglesia.','Enable the assistant in your account. If your administrator registered your number, send Hola to the church WhatsApp.') }}</li><li>{{ tr('Escribe tu solicitud con tus propias palabras o usa uno de los comandos de abajo.','Write your request in your own words or use one of the commands below.') }}</li><li>{{ tr('Revisa el borrador y contesta las preguntas. Para guardar un evento, envía CONFIRMAR como un mensaje separado.','Review the draft and answer follow-up questions. To save an event, send CONFIRMAR as a separate message.') }}</li></ol><router-link to="/whatsapp-settings" class="btn btn-outline-secondary">{{ tr('Ver número y conexión de mi cuenta','View my account connection and destination number') }}</router-link><p class="mt-3">{{ tr('Superadmin: la vista de trabajo no vincula tu cuenta como otro usuario. Usa una cuenta de la iglesia para conversar con el asistente.','Superadmin: work context does not link your account as another user. Use a church account to chat with the assistant.') }}</p></section>
  <p class="wa-example-note">{{ tr('Los ejemplos son modelos: cambia la fecha, lugar, número de evento y objetivo por datos reales. Copiar no envía el mensaje.','Examples are templates: replace the date, location, event number and objective with real values. Copying does not send a message.') }}</p>
  <p v-if="copyNotice" role="status">{{ copyNotice }}</p>
  <div class="wa-tools"><article v-for="item in items" :key="item.name" class="management-surface"><h2>{{ item.name }}</h2><p>{{ item.description }}</p><p><strong>{{ tr('Quién puede usarlo','Who can use it') }}:</strong> {{ item.permission }}</p><div class="wa-example"><span>{{ tr('Ejemplo de mensaje','Example message') }}</span><code>{{ item.example }}</code><button type="button" class="btn btn-outline-secondary" :aria-label="tr('Copiar ejemplo: ','Copy example: ')+item.name" @click="copyExample(item.example)">{{ tr('Copiar ejemplo','Copy example') }}</button></div><p class="mt-3">{{ item.limit }}</p></article></div>
  <aside class="management-surface p-3 mt-3"><h2>{{ tr('Reglas comunes','Shared rules') }}</h2><p>{{ tr('Requiere número vinculado, consentimiento del usuario, iglesia piloto habilitada y permisos actuales. Las solicitudes de lenguaje natural usan IA; los comandos directos no. Se aplican límites por iglesia y usuario. No aprueba, rechaza, publica ni reabre eventos por chat. No maneja inventario, presupuestos, miembros ni juntas.','Requires a linked number, user opt-in, enabled pilot church and current permissions. Natural-language requests use AI; direct commands do not. Church and user limits apply. Chat cannot approve, reject, publish or reopen events. Inventory, budgets, members and meetings are not managed through chat.') }}</p></aside>
 </section>
</template>
<script setup>
import {computed,ref} from 'vue'
import {useUiStore} from '../../stores/uiStore'
import '../../styles/clerk-management.css'
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const copyNotice=ref('')
async function copyExample(text){
 try{await navigator.clipboard.writeText(text);copyNotice.value=tr('Ejemplo copiado. Ajusta los datos antes de enviarlo.','Example copied. Adjust the details before sending.')}
 catch{copyNotice.value=tr('No se pudo copiar automáticamente. Selecciona y copia el texto del ejemplo.','Unable to copy automatically. Select and copy the example text.')}
}
const items=computed(()=>[
 {name:tr('Vincular cuenta','Link account'),description:tr('Un número registrado por el encargado se activa al escribir por primera vez. Si no está registrado, se usa el código de la cuenta.','A pre-registered number activates on its first message. Otherwise, use the account linking code.'),permission:tr('Usuarios habilitados de la iglesia piloto','Enabled pilot church users'),example:'Hola',limit:tr('El código vence en diez minutos. Nunca compartas códigos.','The code expires in ten minutes. Never share codes.')},
 {name:tr('Crear evento departamental','Create department event'),description:tr('Recopila título, fecha, inicio, fin, zona horaria, lugar y objetivo. Prepara una reserva y envía a revisión al confirmar.','Collects title, date, start, end, time zone, location and objective. Prepares a hold and submits for review on confirmation.'),permission:tr('Usuario de departamento con escritura y permiso de crear eventos','Department user with calendar write and event creation permission'),example:tr('Crea un ensayo el 25 de noviembre, de 15:00 a 17:00, zona America/New_York, objetivo 3.','Create a rehearsal November 25, 15:00–17:00, America/New_York, objective 3.'),limit:tr('Objetivo obligatorio. Reserva de cinco minutos. CONFIRMAR no significa aceptación del comité.','Objective required. Five-minute hold. CONFIRMAR does not mean committee approval.')},
 {name:tr('Crear evento de conferencia','Create conference event'),description:tr('Prepara un borrador sin objetivo departamental. CONFIRMAR guarda y bloquea el horario.','Prepares a draft without a department objective. CONFIRMAR saves and blocks the time.'),permission:tr('Secretaría u otro rol con permiso para crear eventos de conferencia','Clerk or another role allowed to create conference events'),example:tr('Crea un evento de conferencia: capacitación, 25 de noviembre, 15:00 a 17:00, zona America/New_York.','Create a conference event: training, November 25, 15:00–17:00, America/New_York.'),limit:tr('No se publica automáticamente. Los eventos departamentales en conflicto pasan a cambios solicitados; las reservas se cancelan. No se bloquea antes de confirmar.','Not published automatically. Conflicting department events receive change requests; holds are cancelled. No time is blocked before confirmation.')},
 {name:'EDITAR <número>',description:tr('Prepara cambios y reenvía el mismo evento con CONFIRMAR.','Prepares changes and resubmits the same event with CONFIRMAR.'),permission:tr('Departamento propietario con permiso de actualizar','Owning department with update permission'),example:'EDITAR 42',limit:tr('Solo eventos con cambios solicitados. No edita eventos aceptados ni eventos de conferencia.','Only events with changes requested. Does not edit accepted or conference events.')},
 {name:'OBJETIVOS / ESTADO',description:tr('Lista objetivos o los diez eventos más recientes del departamento. Para secretaría sin departamento, ESTADO lista sus eventos de conferencia.','Lists objectives or the department’s ten latest events. For a clerk without a department, ESTADO lists their conference events.'),permission:tr('Lectura del módulo correspondiente','Read access to the corresponding module'),example:'OBJETIVOS',limit:tr('Hasta 30 objetivos. ESTADO no muestra todos los eventos de la iglesia.','Up to 30 objectives. ESTADO does not list the entire church calendar.')},
 {name:'CONFIRMAR / EXTENDER / CANCELAR',description:tr('Envía el borrador, renueva la reserva cinco minutos o cancela el borrador.','Submits the draft, renews a hold for five minutes or cancels the draft.'),permission:tr('Cuenta habilitada y permisos del evento','Enabled account and event permissions'),example:'EXTENDER',limit:tr('EXTENDER solo aplica a reservas departamentales activas. Los permisos se verifican de nuevo al confirmar.','EXTENDER only applies to active department holds. Permissions are checked again at confirmation.')},
 {name:tr('Consultar visitas','Query visitors'),description:tr('Devuelve la cantidad de registros en un rango de fechas y un enlace al listado.','Returns the count of records in a date range and a link to the list.'),permission:tr('Pastor, secretaría u otro usuario con acceso de lectura a visitas','Pastor, clerk or another user with visitors read access'),example:tr('¿Cuántos visitantes se registraron del 1 al 19 de noviembre de 2026?','How many visitors were recorded November 1–19, 2026?'),limit:tr('Cuenta por fecha de registro (UTC), no por asistencia. El enlace requiere iniciar sesión. No genera PDF ni reportes de varios sábados separados; puedes consultar cada fecha por separado.','Counts by registration date (UTC), not attendance. The link requires login. PDF generation and reports combining separate Saturdays are not available; query each date separately.')},
 {name:'AYUDA / BAJA',description:tr('Muestra instrucciones o desactiva el asistente para la cuenta.','Shows instructions or disables the assistant for the account.'),permission:tr('Cuenta vinculada y habilitada','Linked and enabled account'),example:'AYUDA',limit:tr('STOP y DESACTIVAR también desactivan. Descarta trabajo pendiente; para reactivar usa la configuración de tu cuenta.','STOP and DESACTIVAR also disable it. Pending work is discarded; re-enable through account settings.')}
])
</script>
<style scoped>
.wa-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.wa-tools article{padding:20px;min-width:0}.wa-tools h2,aside h2{font-size:1rem}.wa-tools p,aside p{font-size:.8125rem}.wa-tools code{display:block;white-space:normal;overflow-wrap:anywhere;background:#eef4f0;padding:10px;border-radius:8px;color:#31543e}@media(max-width:700px){.wa-tools{grid-template-columns:1fr}}

.wa-start{padding:20px;margin-bottom:18px}.wa-start h2{font-size:1rem}.wa-start li{margin-bottom:8px;font-size:.875rem}.wa-start p,.wa-example-note{font-size:.8125rem;color:#53675b}.wa-example{padding:12px;border-radius:10px;background:#eef4f0}.wa-example>span{font-size:.75rem;color:#53675b}.wa-example code{padding:10px 0}.wa-example .btn,.wa-start .btn{width:auto;font-size:.8125rem}
</style>
